DATA['topics'][0]['technical'] = DATA['topics'][0]['technical'].replace(_d8_expansion_marker, '<section class="worked-mechanism" id="d8-userspace-oom"><p class="mechanism-title"><strong>Userspace OOM handling (optional)</strong></p><ul><li><strong class="side-heading">What it is in general:</strong> systemd-oomd uses configured cgroup/PSI policy to select eligible groups on supported systems. earlyoom uses a separate memory/swap-availability policy. A userspace kill can also yield SIGKILL; exit 137 does not identify its actor.</li><li><strong class="side-heading">Relevance to a cloud architect:</strong> Distinguish memory.high direct-reclaim pressure, memory.max failure and daemon policy. zram is compressed RAM-backed block storage that can provide swap; it consumes RAM/CPU rather than creating unlimited physical capacity.</li><li><strong class="side-heading">Relevance to GCP:</strong> Do not assume a VM image enables either daemon or zram. Establish service state, configuration, scope and timestamps before attributing a restart to an image default or kernel limit.</li><li><strong class="side-heading">Concrete example:</strong> On a system already using it, read <kbd>systemctl status systemd-oomd --no-pager</kbd> and <kbd>journalctl -u systemd-oomd --since "10 minutes ago" --no-pager</kbd>. Compare with kernel OOM and cgroup records; no service is enabled or reconfigured.</li><li><strong class="side-heading">Evidence limit:</strong> Features depend on installed versions/configuration. Missing records do not rule out another killer. No OOM, swap exhaustion or zram setup is induced.</li><li><strong class="side-heading">Further study:</strong> <a href="https://man7.org/linux/man-pages/man8/systemd-oomd.service.8.html#DESCRIPTION">systemd-oomd DESCRIPTION (accessed 2026-10-16)</a>; <a href="https://github.com/rfjakob/earlyoom#user-content-what-does-it-do">earlyoom What does it do (accessed 2026-10-16)</a>; <a href="https://docs.kernel.org/admin-guide/blockdev/zram.html">zram documentation (accessed 2026-10-16)</a></li></ul></section>' + _d8_expansion_marker, 1)

_d8_expansion_marker = '<h4>Structured data parsing with jq: JSON filters, nested traversal, and numeric selections</h4>'
